using System.Globalization;
using System.Text;
using RecursiveAI.OneCrypto.OpenPgp.Packets;

namespace RecursiveAI.OneCrypto.OpenPgp.Tests;

/// <summary>
/// Round trip and fingerprints over a corpus generated by the oracles (tools/oracles/corpus-*.sh), laid out as
/// &lt;corpus&gt;/&lt;oracle&gt;/&lt;kind&gt;/NAME.{pgp,asc}. The corpus is not committed; point ONECRYPTO_OPENPGP_CORPUS at it
/// (default ~/onecrypto/corpus/openpgp). The tests skip when it is absent. A summary of counts per oracle and kind is written to
/// $ONECRYPTO_ARTIFACTS/openpgp-corpus-summary.txt.
/// </summary>
public class CorpusTests
{
    private static string Root => Environment.GetEnvironmentVariable("ONECRYPTO_OPENPGP_CORPUS")
        ?? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "onecrypto", "corpus", "openpgp");

    private static IEnumerable<string> Files() =>
        Directory.Exists(Root)
            ? Directory.EnumerateFiles(Root, "*", SearchOption.AllDirectories).Where(f => f.EndsWith(".pgp", StringComparison.Ordinal) || f.EndsWith(".asc", StringComparison.Ordinal) || f.EndsWith(".gpg", StringComparison.Ordinal) || f.EndsWith(".sig", StringComparison.Ordinal)).Order(StringComparer.Ordinal)
            : [];

    private static (string Oracle, string Kind) Classify(string file)
    {
        string[] parts = Path.GetRelativePath(Root, file).Split(Path.DirectorySeparatorChar);
        return (parts.Length > 1 ? parts[0] : "?", parts.Length > 2 ? parts[1] : "?");
    }

    private static bool IsCleartext(byte[] bytes) => Encoding.ASCII.GetString(bytes, 0, Math.Min(bytes.Length, 64)).StartsWith("-----BEGIN PGP SIGNED MESSAGE-----", StringComparison.Ordinal);

    [Fact]
    public void EveryCorpusFileParsesAndWritesBackIdentically()
    {
        var files = Files().ToList();
        Assert.SkipWhen(files.Count == 0, "no corpus at " + Root);
        var counts = new SortedDictionary<string, int[]>(StringComparer.Ordinal);
        var failures = new List<string>();
        var unrecognized = new SortedDictionary<string, int>(StringComparer.Ordinal);
        foreach (string file in files)
        {
            (string oracle, string kind) = Classify(file);
            string key = oracle + "/" + kind;
            int[] c = counts.TryGetValue(key, out int[]? existing) ? existing : counts[key] = new int[3];
            byte[] raw = File.ReadAllBytes(file);
            if (IsCleartext(raw))
            {
                c[2]++;
                continue;
            }

            try
            {
                byte[] binary = Armor.LooksArmored(raw[0]) ? Armor.Decode(raw).Data : raw;
                IReadOnlyList<Packet> packets = PacketParser.ParseAll(binary);
                using var ms = new MemoryStream();
                PacketParser.Write(packets, ms);
                if (!ms.ToArray().AsSpan().SequenceEqual(binary))
                {
                    failures.Add(file + ": rewritten bytes differ");
                    continue;
                }

                // The same input through a stream, whose packets cannot share the input's memory.
                using var ms2 = new MemoryStream();
                PacketParser.Write(PacketParser.ParseAll(new MemoryStream(binary)), ms2);
                if (!ms2.ToArray().AsSpan().SequenceEqual(binary))
                {
                    failures.Add(file + ": streamed rewrite differs");
                    continue;
                }

                foreach (Packet p in packets.OfType<UnrecognizedPacket>())
                {
                    string tag = oracle + " tag " + p.TagId.ToString(CultureInfo.InvariantCulture) + " version " + (p as UnrecognizedPacket)!.FirstOctet;
                    unrecognized[tag] = unrecognized.GetValueOrDefault(tag) + 1;
                }

                c[0]++;
            }
            catch (OpenPgpParseException e)
            {
                c[1]++;
                failures.Add(file + ": " + e.Message);
            }
        }

        var sb = new StringBuilder();
        sb.AppendLine("oracle/kind: parsed-and-identical, failed, cleartext-skipped");
        foreach (KeyValuePair<string, int[]> kv in counts)
        {
            sb.AppendLine(string.Create(CultureInfo.InvariantCulture, $"{kv.Key}: {kv.Value[0]}, {kv.Value[1]}, {kv.Value[2]}"));
        }

        foreach (KeyValuePair<string, int> kv in unrecognized)
        {
            sb.AppendLine(string.Create(CultureInfo.InvariantCulture, $"preserved as unrecognized: {kv.Key}: {kv.Value}"));
        }

        string? dir = Environment.GetEnvironmentVariable("ONECRYPTO_ARTIFACTS");
        if (dir is not null)
        {
            Directory.CreateDirectory(dir);
            File.WriteAllText(Path.Combine(dir, "openpgp-corpus-summary.txt"), sb.ToString());
        }

        Assert.True(failures.Count == 0, string.Join('\n', failures.Take(20)) + "\n" + sb);
    }

    private static IEnumerable<string> FprFiles() =>
        Directory.Exists(Root) ? Directory.EnumerateFiles(Root, "*.fpr", SearchOption.AllDirectories).Order(StringComparer.Ordinal) : [];

    [Fact]
    public void FingerprintsMatchTheOraclesListing()
    {
        var checkedFiles = new List<string>();
        var failures = new List<string>();
        foreach (string fpr in FprFiles())
        {
            string stem = fpr[..^4];
            foreach (string ext in new[] { ".pgp", ".asc" })
            {
                if (!File.Exists(stem + ext))
                {
                    continue;
                }

                byte[] raw = File.ReadAllBytes(stem + ext);
                byte[] binary = Armor.LooksArmored(raw[0]) ? Armor.Decode(raw).Data : raw;
                var keys = TransferableKey.ParseAll(PacketParser.ParseAll(binary));
                string ours = string.Join(',', keys.SelectMany(k => k.Packets.OfType<KeyPacket>().Select(p => p.FingerprintHex)));
                string theirs = string.Join(',', File.ReadAllLines(fpr).Where(l => l.StartsWith("fpr:", StringComparison.Ordinal)).Select(l => l[4..].ToUpperInvariant()));
                if (ours != theirs)
                {
                    failures.Add($"{stem + ext}: ours {ours} theirs {theirs}");
                }

                checkedFiles.Add(stem + ext);
            }
        }

        Assert.SkipWhen(checkedFiles.Count == 0, "no corpus fingerprints at " + Root);
        Assert.True(failures.Count == 0, string.Join('\n', failures.Take(10)));
    }
}
